import {EXERCISES,EQUIPMENT,GOALS,exerciseById} from './exercises.js';
import {uid,defaultProfile,todayISO,addDays,dayOf,difference,eligible,loadFor,estimateItem,estimateSession,createPlan,scheduleConflicts,substitutions,progressionFor,calendarICS} from './planner.js';
import {mountModel} from './model.js';
import {validState,validProfile} from './storage.js';
import {shortenSession,repeatRunningWeek} from './adaptation.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DAYS=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const KEY='home-training-state-v1',DRAFT='home-training-draft-v1';
let storageOK=true,toastHandle,models=[],modalModel=null,tick=null,screen='home',weekOffset=0,libraryQuery='',libraryPattern='all',libraryAvailability='all',selectedExercise=null;
const blank=()=>({version:1,profile:null,sessions:[],history:[],active:null,planSummary:'',planWarnings:[],progressionApplied:{}});
let state=blank();
try{const raw=localStorage.getItem(KEY);if(raw){const loaded=JSON.parse(raw);if(validState(loaded))state=loaded;else throw Error('Invalid saved data');}}catch{storageOK=false;}
state.progressionApplied??={};
let setupDraft=state.profile?structuredClone(state.profile):defaultProfile();
try{const draft=JSON.parse(localStorage.getItem(DRAFT)||'null');if(validProfile(draft))setupDraft=draft;}catch{}
const dateLabel=(iso,options={weekday:'short',month:'short',day:'numeric'})=>new Intl.DateTimeFormat('en-GB',{...options,timeZone:'UTC'}).format(new Date(iso+'T12:00:00Z'));
const today=()=>todayISO(state.profile?.timezone||'Africa/Nairobi');
const minutes=s=>Math.ceil((s.kind==='run'?s.runMinutes*60:estimateSession(s))/60);
const clock=n=>`${Math.floor(Math.max(0,n)/60).toString().padStart(2,'0')}:${Math.floor(Math.max(0,n)%60).toString().padStart(2,'0')}`;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('Your browser could not save this change. Export a backup before closing.');}return storageOK;}
function saveDraft(){try{localStorage.setItem(DRAFT,JSON.stringify(setupDraft));}catch{}}
function toast(message){clearTimeout(toastHandle);const el=$('#toast');el.textContent=message;el.hidden=false;toastHandle=setTimeout(()=>el.hidden=true,5000);}
function download(content,name,type='application/json'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function cleanup(){models.forEach(m=>m.dispose());models=[];if(tick){clearInterval(tick);tick=null;}}
function closeDialog(){modalModel?.dispose();modalModel=null;$('#dialog').close();$('#dialog').innerHTML='';}
$('#dialog').addEventListener('close',()=>{modalModel?.dispose();modalModel=null;});
function dialog(title,body,footer=''){modalModel?.dispose();modalModel=null;$('#dialog').innerHTML=`<div class="dialog-head"><h2>${escape(title)}</h2><button class="quiet-button" type="button" data-action="close" aria-label="Close dialog">×</button></div>${body}${footer?`<div class="dialog-foot">${footer}</div>`:''}`;if(!$('#dialog').open)$('#dialog').showModal();}
function navButton(id,label,icon){return `<button type="button" data-nav="${id}" class="${screen===id?'active':''}" ${screen===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${label}</button>`;}
function shell(body){const p=state.profile;return `<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">h</span><div>Home training<small>Make room for movement</small></div></div><nav class="nav" aria-label="Main navigation">${navButton('home','Overview','⌂')}${navButton('schedule','Your schedule','▦')}${navButton('library','Exercise library','◇')}${navButton('progress','Your progress','↗')}${navButton('settings','Your setup','⚙')}</nav><div class="sidebar-bottom"><span class="privacy-dot"></span>Saved on this device<br>Your training, at your pace.<br><button class="text-link" style="color:#c5d2c2" data-action="about">About this planner</button></div></aside><div class="main"><header class="topbar"><div><div class="greeting">${p?.name?`Hello, ${escape(p.name)}`:'Your personal training space'}</div><div class="date">${dateLabel(today(),{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</div></div><div class="top-actions"><span class="save-state">${storageOK?'Saved on this device':'Browser saving unavailable'}</span><span class="avatar" aria-label="Your profile">${escape((p?.name||'You').slice(0,1).toUpperCase())}</span></div></header><main id="main" class="content">${body}</main></div></div><nav class="mobile-nav" aria-label="Mobile navigation">${navButton('home','Overview','⌂')}${navButton('schedule','Schedule','▦')}${navButton('library','Exercises','◇')}${navButton('progress','Progress','↗')}${navButton('settings','Setup','⚙')}</nav>`;}
function header(title,description,actions=''){return `<div class="page-head"><div><div class="eyebrow">${screen==='settings'?'Your starting point':'Home training'}</div><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${actions?`<div class="button-row">${actions}</div>`:''}</div>`;}
function render(){cleanup();if(screen==='settings')renderSetup();else{let body=screen==='home'?home():screen==='schedule'?schedule():screen==='library'?library():screen==='progress'?progress():screen==='workout'?workout():home();$('#app').innerHTML=shell(body);mountPage();}document.title=screen==='workout'?'Your session · Home training':'Home training';}
function go(name){if(screen==='settings')captureSetup();screen=name;render();window.scrollTo({top:0,behavior:'instant'});}
function empty(title,copy,button='Make your plan',action='setup'){return `<div class="card empty"><span class="brand-mark">h</span><h2>${title}</h2><p>${copy}</p><button class="primary" data-action="${action}">${button}</button></div>`;}
function nextSession(){if(state.active)return state.sessions.find(s=>s.id===state.active.sessionId);return state.sessions.filter(s=>s.status==='planned').sort((a,b)=>a.date.localeCompare(b.date))[0];}
function sessionRow(s){return `<div class="list-row"><div class="day-badge">${dateLabel(s.date,{weekday:'short'})}<b>${Number(s.date.slice(-2))}</b></div><div class="grow"><p><strong>${escape(s.title)}</strong></p><small>${s.kind==='run'?'Outdoors':s.location==='gym'?'At the gym':'At home'} &nbsp; ${minutes(s)} min</small></div><button class="quiet-button" data-action="open-session" data-id="${s.id}" aria-label="Open ${escape(s.title)} on ${s.date}">↗</button></div>`;}
function home(){const s=nextSession();if(!state.profile)return header('A plan that fits your life.','Start with your goals, the equipment you have and the time you can make.')+empty('Let’s find your starting rhythm.','Build your first week, learn each movement, and keep a record of what you complete.');const upcoming=state.sessions.filter(x=>x.status==='planned').sort((a,b)=>a.date.localeCompare(b.date));const weekStart=addDays(today(),-((dayOf(today())+6)%7));const done=state.history.filter(h=>h.date>=weekStart);const totalSets=state.history.reduce((n,h)=>n+h.sets.length,0);return header('A little stronger, week by week.','Your next step is ready. Keep showing up and let the record guide what comes next.',`<button class="secondary" data-nav="schedule">View your schedule ↗</button>`)+`${state.active?`<div class="welcome-banner"><p>You have a session in progress. Your recorded sets are saved.</p><button class="secondary" data-action="resume">Resume session</button></div>`:''}${!storageOK?'<div class="error">Browser saving is unavailable. Export a backup from Your setup before closing.</div>':''}<div class="dashboard-grid"><section class="card next-card"><div class="next-content"><div class="eyebrow">${s?difference(s.date,today())<0?'Ready when you are':s.date===today()?'Up next today':'Your next session':'Your starting block is complete'}</div><h2>${s?escape(s.title):'Time to reflect.'}</h2><p>${s?escape(s.kind==='run'?s.note:'A focused session using your '+(s.location==='gym'?'gym':'home')+' equipment. Warm up, take your time and record each set.'):'Review your progress and create the next block from your current setup.'}</p><div class="pillset">${s?`<span class="pill dark">${minutes(s)} minutes</span><span class="pill outline">${s.kind==='run'?'Running':GOALS[state.profile.goal]}</span><span class="pill outline">${dateLabel(s.date)}</span>`:'<span class="pill dark">Block complete</span>'}</div><div class="button-row">${s?`<button class="primary" data-action="open-session" data-id="${s.id}">${state.active?'Resume session':'See your session'} <span aria-hidden="true">→</span></button>`:'<button class="primary" data-nav="settings">Plan the next block</button>'}</div></div><div class="mini-art"><canvas id="hero-model" aria-hidden="true"></canvas></div></section><section class="card"><div class="section-head"><h3>This week</h3><span class="pill">${state.profile.days.length} available days</span></div><div class="week-strip">${Array.from({length:7},(_,i)=>{const d=addDays(weekStart,i);const sess=state.sessions.find(x=>x.date===d&&x.status!=='skipped');return `<div class="week-tile ${sess?'work':''} ${d===today()?'today':''} ${sess?.status==='completed'?'done':''}"><span>${DAYS[dayOf(d)].slice(0,1)}</span><b>${Number(d.slice(-2))}</b><span class="dot"></span></div>`;}).join('')}</div><p class="info-line">${done.length} session${done.length===1?'':'s'} recorded this week.</p><div class="statstrip"><div class="stat"><span>Sessions</span><strong>${state.history.length}</strong><small>recorded so far</small></div><div class="stat"><span>Working sets</span><strong>${totalSets}</strong><small>actually logged</small></div><div class="stat"><span>Minutes</span><strong>${Math.round(state.history.reduce((n,h)=>n+(h.durationSeconds||0),0)/60)}</strong><small>recorded time</small></div></div><button class="text-link" data-nav="progress">See your progress →</button></section><section class="card"><div class="section-head"><h3>Coming up</h3><button class="text-link" data-nav="schedule">Full schedule</button></div>${upcoming.slice(0,4).map(sessionRow).join('')||'<p class="muted">No planned sessions remain.</p>'}</section><section class="card"><div class="eyebrow">Built around you</div><h3>${escape(GOALS[state.profile.goal])}</h3><p class="info-line">${escape(state.planSummary)}</p><div class="pillset"><span class="pill">${state.profile.dumbbellKg} kg dumbbells</span><span class="pill">${state.profile.days.length} days available</span></div>${state.planWarnings.map(w=>`<p class="small muted">${escape(w)}</p>`).join('')}<div class="detail-group"><h3>Learn before you lift</h3><p>Rotate the movement guides, read the form cues, and choose a variation you can control.</p><button class="text-link" data-nav="library">Explore your exercises →</button></div><p class="footer-note">Your records stay in this browser. Export a backup when switching devices.</p></section></div>`;}
function schedule(){if(!state.profile)return header('Your schedule','A week built around your availability.')+empty('Start with your available time.','Choose your days and session lengths to build a schedule.');const start=addDays(today(),-((dayOf(today())+6)%7)+weekOffset*7);return header('Make room for movement.','Move a session when life changes. Keep the recovery your plan needs.',`<button class="secondary" data-action="export-calendar">Export calendar ↗</button><button class="primary" data-nav="settings">Edit your plan</button>`)+`<div class="week-toolbar"><div class="button-row"><button class="button" data-action="prev-week" aria-label="Previous week">←</button><button class="button" data-action="this-week">This week</button><button class="button" data-action="next-week" aria-label="Next week">→</button></div><h2>${dateLabel(start,{month:'short',day:'numeric'})} to ${dateLabel(addDays(start,6),{month:'short',day:'numeric',year:'numeric'})}</h2></div><div class="schedule-grid">${Array.from({length:7},(_,i)=>{const d=addDays(start,i);const list=state.sessions.filter(s=>s.date===d);return `<section class="schedule-day ${d===today()?'today':''}"><div class="day-header"><span>${DAYS[dayOf(d)].slice(0,3).toUpperCase()}</span><b>${Number(d.slice(-2))}</b></div><div>${list.map(s=>`<div class="session-tile ${s.status!=='planned'?'complete':''}"><span class="pill">${s.status==='planned'?s.kind==='run'?'Run':'Strength':s.status}</span><h3>${escape(s.title)}</h3><p>${minutes(s)} min &nbsp; ${s.kind==='run'?`${s.km?`${s.km} km`:'Run and walk'}`:escape(s.location)}</p><button class="button" data-action="open-session" data-id="${s.id}">${s.status==='planned'?'Open':'View'}</button></div>`).join('')||'<p class="recovery">Recovery day<br>Rest or move gently.</p>'}</div></section>`;}).join('')}</div><p class="footer-note">Calendar export uses ${escape(state.profile.time)} in ${escape(state.profile.timezone)} with a 15 minute reminder. Your calendar app handles reminders after import. Later changes require a new export.</p>`;}
function renderSetup(){const p=setupDraft;const eq=location=>EQUIPMENT.map(([key,label])=>`<label class="check"><input type="checkbox" name="equipment-${location}" value="${key}" ${(p.equipment[location]||[]).includes(key)?'checked':''}>${label}</label>`).join('');$('#app').innerHTML=shell(header(state.profile?'Keep your plan in step with you.':'Find your starting rhythm.','Choose a priority, confirm your equipment and make space in your week.')+`<form id="setup-form"><div class="form-layout"><div><section class="card form-card"><div class="eyebrow">01 &nbsp; Your direction</div><h2>What are you working towards?</h2><p class="small muted">One main goal keeps the programme focused.</p><div class="form-row"><label class="field">Your name, optional<input name="name" maxlength="40" autocomplete="given-name" value="${escape(p.name)}" placeholder="What should we call you?"></label><label class="field">Main goal<select name="goal">${Object.entries(GOALS).map(([v,t])=>`<option value="${v}" ${p.goal===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="form-row"><label class="field">Secondary priority<select name="secondary"><option value="">None</option>${Object.entries(GOALS).filter(([v])=>!['running','marathon'].includes(v)).map(([v,t])=>`<option value="${v}" ${p.secondary===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Recent experience<select name="experience"><option value="0" ${p.experience===0?'selected':''}>New or returning to training</option><option value="1" ${p.experience===1?'selected':''}>Training regularly</option><option value="2" ${p.experience===2?'selected':''}>Experienced with these movements</option></select></label></div><label class="check"><input type="checkbox" name="adult" ${p.adult?'checked':''}>I’m 18 or older.</label><label class="check"><input type="checkbox" name="individual" ${p.individual?'checked':''}>A health condition, pregnancy, injury recovery or professional restriction means I need an individual programme.</label><p class="small muted">This planner offers general training drafts. It does not assess injuries or replace an individual programme.</p></section>
<section class="card form-card"><div class="eyebrow">02 &nbsp; Your week</div><h2>Time you can actually make.</h2><p class="small muted">Warm-up, rest and finishing time all count. Choose home or gym for each day.</p>${[1,2,3,4,5,6,0].map(d=>`<div class="day-input"><input type="checkbox" name="day" value="${d}" ${p.days.includes(d)?'checked':''} aria-label="Train on ${DAYS[d]}"><span>${DAYS[d]}</span><input type="number" name="minutes-${d}" min="15" max="300" value="${p.slots[d]}" aria-label="Minutes on ${DAYS[d]}"><select name="location-${d}" aria-label="Location on ${DAYS[d]}"><option value="home" ${p.locations[d]==='home'?'selected':''}>Home</option><option value="gym" ${p.locations[d]==='gym'?'selected':''}>Gym</option></select></div>`).join('')}<div class="form-row"><label class="field">Starting date<input type="date" name="start" value="${escape(p.start)}" required></label><label class="field">Usual workout time<input type="time" name="time" value="${escape(p.time)}" required></label></div><label class="field">Calendar timezone<select name="timezone">${['Africa/Nairobi','UTC','Europe/London','America/New_York','Asia/Dubai','Asia/Kolkata','Australia/Sydney'].map(t=>`<option ${p.timezone===t?'selected':''}>${t}</option>`).join('')}</select></label></section>
<section class="card form-card"><div class="eyebrow">03 &nbsp; Your equipment</div><h2>Use what you have.</h2><div class="form-row"><label class="field">Weight of each dumbbell in kg<input name="dumbbellKg" type="number" step="0.5" min="0.5" max="200" value="${p.dumbbellKg}" required></label><label class="field">Band label<input name="band" value="${escape(p.band)}" maxlength="40" placeholder="For example, medium loop"></label></div><h3>At home</h3><p class="small muted">Confirm the items and band types you actually have. Leave uncertain equipment off.</p><div class="equipment-grid">${eq('home')}</div><details class="detail-group"><summary>Equipment at the gym</summary><div class="equipment-grid">${eq('gym')}</div></details><label class="check"><input type="checkbox" name="wheelReady" ${p.wheelReady?'checked':''}>My roller is an ab wheel, and I’m experienced with a controlled kneeling rollout.</label><p class="small muted">An anchor means a suitable band attachment installed according to its instructions. A bench means a stable workout bench. Neither is assumed.</p><details class="detail-group"><summary>Movements to leave out</summary><div class="equipment-grid">${EXERCISES.filter(e=>e.pattern!=='cardio').map(e=>`<label class="check"><input type="checkbox" name="excluded" value="${e.id}" ${p.excluded.includes(e.id)?'checked':''}>${e.name}</label>`).join('')}</div></details></section>
<section class="card form-card" id="running-setup" ${!['running','marathon'].includes(p.goal)?'hidden':''}><div class="eyebrow">04 &nbsp; Your running base</div><h2>Start from your recent running.</h2><p class="small muted">Use recent, comfortable training rather than your all time best.</p><div class="form-row"><label class="field">Current weekly distance in km<input type="number" name="runningKm" min="0" max="300" step="1" value="${p.runningKm}"></label><label class="field">Longest recent run in km<input type="number" name="longestKm" min="0" max="100" step="0.5" value="${p.longestKm}"></label></div><div class="form-row"><label class="field">Easy pace in minutes per km<input type="number" name="pace" min="3" max="15" step="0.1" value="${p.pace}"></label><label class="field">Race date, for marathon<input type="date" name="raceDate" value="${escape(p.raceDate)}"></label></div><label class="field">Long run day<select name="longDay">${DAYS.map((d,i)=>`<option value="${i}" ${Number(p.longDay)===i?'selected':''}>${d}</option>`).join('')}</select></label><p class="small muted">Marathon drafts need four running days, an established base, and a long run slot of at least three hours. The planner checks the exact schedule before creating it.</p></section></div>
<aside class="card sticky"><div class="eyebrow">Your plan preview</div><h2>A starting point you can change.</h2><p class="info-line">${state.profile?'Creating a new block replaces only future planned sessions. Your completed workouts and history stay intact.':'Build a preview before anything enters your schedule.'}</p><div class="preview-summary"><h3>How it works</h3><ul><li>Only suitable equipment and movements are selected.</li><li>The whole session fits the time you choose.</li><li>Recovery stays part of the week.</li><li>Results guide future adjustments.</li></ul></div><div id="plan-errors" role="alert"></div><button type="submit" class="primary full">Preview my programme →</button><p class="footer-note">Your setup saves on this device. No health information is sent to an exercise provider.</p></aside></div></form>`);}
function captureSetup(){const form=$('#setup-form');if(!form)return;const f=new FormData(form);const p={...setupDraft};for(const k of ['name','goal','secondary','start','time','timezone','band','raceDate'])p[k]=String(f.get(k)||'');for(const k of ['experience','dumbbellKg','runningKm','longestKm','pace','longDay'])p[k]=Number(f.get(k));for(const k of ['adult','individual','wheelReady'])p[k]=f.has(k);p.days=f.getAll('day').map(Number);p.excluded=f.getAll('excluded');p.equipment={home:f.getAll('equipment-home'),gym:f.getAll('equipment-gym')};p.slots={};p.locations={};for(let d=0;d<7;d++){p.slots[d]=Number(f.get(`minutes-${d}`));p.locations[d]=f.get(`location-${d}`);}setupDraft=p;saveDraft();}
let pendingPlan=null;
function previewPlan(){captureSetup();if(state.active){toast('Finish or save your current session before replacing the planned block.');return;}const result=createPlan(setupDraft);if(result.errors.length){$('#plan-errors').innerHTML=`<div class="error">${result.errors.map(e=>`<p>${escape(e)}</p>`).join('')}</div>`;$('#plan-errors').scrollIntoView({behavior:'smooth',block:'center'});return;}pendingPlan=result;const first=result.sessions.slice(0,5);dialog('Your programme preview',`<p class="muted">${escape(result.summary)}</p><div class="pillset"><span class="pill">${GOALS[setupDraft.goal]}</span><span class="pill">${result.sessions.length} sessions</span></div>${result.warnings.map(w=>`<div class="notice">${escape(w)}</div>`).join('')}${first.map(s=>`<div class="list-row"><div class="grow"><p><strong>${escape(s.title)}</strong></p><small>${dateLabel(s.date)} &nbsp; ${minutes(s)} min &nbsp; ${escape(s.location)}</small></div></div>`).join('')}<p class="footer-note">You can move or skip sessions after adding them. Existing completed records are kept.</p>`,`<button class="secondary" data-action="close">Keep editing</button><button class="primary" data-action="accept-plan">Use this programme</button>`);}
function library(){const p=state.profile||setupDraft;const filtered=EXERCISES.filter(e=>e.name.toLowerCase().includes(libraryQuery.toLowerCase())&&(libraryPattern==='all'||e.pattern===libraryPattern)&&(libraryAvailability==='all'||eligible(e,p,libraryAvailability)));return header('Know the movement.','Explore original 3D guides, learn the form cues, and find a suitable variation.')+`<div class="library-controls"><input id="exercise-search" type="search" placeholder="Search movements" aria-label="Search exercises" value="${escape(libraryQuery)}"><select id="pattern-filter" aria-label="Movement pattern">${[['all','All movements'],['squat','Squat and single leg'],['hinge','Hip hinge'],['push','Push'],['pull','Pull'],['core','Core'],['calves','Calves'],['arms','Arms'],['cardio','Conditioning']].map(([v,l])=>`<option value="${v}" ${v===libraryPattern?'selected':''}>${l}</option>`).join('')}</select><select id="availability-filter" aria-label="Available equipment"><option value="all" ${libraryAvailability==='all'?'selected':''}>Full library</option><option value="home" ${libraryAvailability==='home'?'selected':''}>Suitable for my home setup</option><option value="gym" ${libraryAvailability==='gym'?'selected':''}>Suitable for my gym setup</option></select></div><div class="exercise-grid">${filtered.map(e=>`<article class="card exercise-card"><div class="exercise-art"><canvas data-preview="${e.id}" aria-hidden="true"></canvas></div><div class="exercise-card-body"><div class="pillset"><span class="pill">${['Foundation','Regular training','Experienced'][e.level]}</span>${e.equipment.some(k=>['cable','barbell','latMachine','legPress','bench'].includes(k))?'<span class="pill outline">Gym</span>':''}</div><h3>${escape(e.name)}</h3><p>${e.muscles.join(', ')}<br>${e.equipment.map(k=>EQUIPMENT.find(x=>x[0]===k)?.[1]||k).join(', ')||'No equipment'}</p><button class="button" data-action="exercise-guide" data-id="${e.id}">Learn the movement ↗</button></div></article>`).join('')||'<div class="card"><p>No exercises match those filters. Try another movement or equipment setting.</p></div>'}</div><p class="footer-note">The figures are simplified movement illustrations. They do not measure or assess your form. Follow the written cues and choose a range you can control.</p>`;}
function modelHTML(e){return `<div class="model-wrap"><canvas id="movement-model" role="img" aria-label="Rotatable animated movement diagram of ${escape(e.name)}. ${escape(e.cues.join(' '))}"></canvas><div class="model-caption"><span>Illustrative 3D movement guide</span><span>Drag to rotate</span></div></div><div class="model-controls"><button class="button" data-model="play">${matchMedia('(prefers-reduced-motion: reduce)').matches?'Play':'Pause'}</button><button class="button" data-model="front">Front view</button><button class="button" data-model="side">Side view</button><select id="model-speed" aria-label="Animation speed"><option value="1">Normal speed</option><option value="0.5">Half speed</option></select><label class="inline-label">Position <input id="model-step" type="range" min="0" max="1" step="0.02" value="0" aria-label="Inspect movement position"></label></div>`;}
function techniqueHTML(e){return `<ol class="cues">${e.cues.map(c=>`<li>${escape(c)}</li>`).join('')}</ol><details class="detail-group"><summary>Why these cues matter</summary><p>${escape(e.why)}</p></details><details class="detail-group"><summary>A common mistake</summary><p>${escape(e.mistake)}</p></details><div class="button-row" style="margin-top:15px"><a class="text-link" href="${e.reference}" target="_blank" rel="noopener noreferrer">Exercise reference ↗</a>${e.easier?`<button class="text-link" data-action="exercise-guide" data-id="${e.easier}">See an easier option</button>`:''}</div>`;}
function exerciseGuide(id){const e=exerciseById(id);if(!e)return;selectedExercise=id;dialog(e.name,`<div class="dialog-exercise">${modelHTML(e)}<div class="pillset">${e.muscles.map(m=>`<span class="pill">${m}</span>`).join('')}</div>${techniqueHTML(e)}</div>`);modalModel=mountModel($('#dialog canvas'),e.motion);}
function startSession(id){const s=state.sessions.find(x=>x.id===id);if(!s)return;if(s.status!=='planned'){showHistoryForSession(id);return;}if(state.active&&state.active.sessionId!==id){toast('Finish your current session first, or save it as a partial session.');go('workout');return;}if(!state.active){const start=()=>{state.active={sessionId:id,index:0,sets:[],blocked:[],startedAt:Date.now(),restUntil:null,runIndex:0,runRemaining:s.segments?.[0]?.seconds||0,runPlaying:false,runCompleted:[],runUpdatedAt:Date.now(),discomfort:false};persist();closeDialog();go('workout');};dialog(s.title,`<p class="muted">${dateLabel(s.date)} &nbsp; ${minutes(s)} minutes &nbsp; ${escape(s.location)}</p><p>${escape(s.note||'Warm up gradually and use a comfortable range for each movement.')}</p>${s.kind==='strength'?`<div class="notice green">Start with about four minutes of easy movement and light practice of the exercises. Finish with three minutes of easy walking and comfortable movement.</div>${s.items.map(i=>{const e=exerciseById(i.exerciseId);return `<div class="list-row"><div class="grow"><p>${e.name}</p><small>${i.sets} sets, ${i.reps}${e.timed?' seconds':' repetitions'}${e.unilateral?' each side':''}</small></div><span class="small muted">${escape(i.load.label)}</span></div>`;}).join('')}`:`<div class="notice green">Use a conversational effort. Walking and recovery are part of the session. You can pause or finish early.</div>${s.km?`<p>Planned distance ${s.km} km, estimated at your easy pace.</p>`:''}`}<div class="button-row" style="margin-top:20px"><button class="secondary" data-action="move-session" data-id="${id}">Move session</button>${s.kind==='strength'?`<button class="secondary" data-action="shorten" data-id="${id}">Shorten session</button>`:''}<button class="quiet-button" data-action="skip-session" data-id="${id}">Skip this session</button></div>`,`<button class="secondary" data-action="close">Back</button><button class="primary" id="begin-session">Start session →</button>`);$('#begin-session').onclick=start;return;}go('workout');}
function activeData(){const a=state.active;return {a,s:a?state.sessions.find(s=>s.id===a.sessionId):null};}
function workout(){const {a,s}=activeData();if(!a||!s)return header('Your session','Everything you need for the next movement.')+empty('No session is in progress.','Open a planned session from your schedule.','View schedule','schedule');if(s.kind==='run')return runningWorkout(a,s);const i=s.items[a.index],e=exerciseById(i.exerciseId),logged=a.sets.filter(x=>x.itemIndex===a.index).length,blocked=a.blocked.includes(a.index);const rest=Math.max(0,Math.ceil(((a.restUntil||0)-Date.now())/1000));return header(s.title,`${dateLabel(s.date)} · ${s.location==='gym'?'At the gym':'At home'} · Estimated ${minutes(s)} minutes`,`<button class="secondary" data-action="shorten" data-id="${s.id}">Shorten session</button><button class="secondary" data-action="finish-session">Finish or save partial</button>`)+`<div class="workout-layout"><section class="card"><div class="section-head"><div><div class="eyebrow">Movement ${a.index+1} of ${s.items.length}</div><h2>${e.name}</h2></div><span class="pill">${e.pattern}</span></div><p class="muted small">${escape(i.load.label)} &nbsp; ${i.sets} sets of ${i.reps}${e.timed?' seconds':' reps'}${e.unilateral?' each side':''}</p>${modelHTML(e)}${techniqueHTML(e)}<div class="log-card"><div class="section-head"><h3>${blocked?'Movement stopped':logged>=i.sets?'Sets recorded':`Set ${logged+1} of ${i.sets}`}</h3><button class="text-link" data-action="swap-exercise">Change exercise</button></div><div class="set-dots">${Array.from({length:i.sets},(_,n)=>`<span class="set-dot ${n<logged?'done':''}" aria-label="Set ${n+1} ${n<logged?'recorded':'remaining'}"></span>`).join('')}</div>${blocked?'<div class="error">You reported discomfort. This movement is stopped and progression is paused. Don’t push through it or treat a substitute as treatment.</div>':logged>=i.sets?`<p class="small muted">Your recorded work is saved. Continue when you feel ready.</p>`:`<form id="set-form"><div class="log-grid"><label class="field">${e.timed?'Seconds':'Reps'} ${e.unilateral?'per side':''}<input type="number" name="reps" min="1" max="300" value="${i.reps}" step="1" required></label><label class="field">${e.load==='pair'?'Kg per hand':e.load==='single'?'Kg held':e.load==='machine'||e.load==='barbell'?'Load in kg':'Load, optional kg'}<input type="number" name="kg" min="0" max="500" step="0.5" value="${i.load.kg||0}" ${e.load==='band'?'disabled':''}></label><label class="field">How much was left?<select name="effort"><option value="more">A few more good reps</option><option value="hard">No more good reps</option><option value="unsure">Not sure</option></select></label></div>${e.load==='band'?`<p class="small muted">Band recorded as ${escape(i.load.label)}. Resistance is not converted to kg.</p>`:''}<button class="primary full" type="submit" style="margin-top:18px">Save this set</button></form>`}<div class="button-row" style="margin-top:15px"><button class="danger-button" data-action="discomfort">Stop for discomfort</button><button class="secondary" data-action="next-exercise">${a.index===s.items.length-1?'Review session':'Next movement →'}</button></div></div></section><aside><section class="card"><div class="section-head"><h3>Your session</h3><span class="small muted">${a.sets.length} sets saved</span></div><div class="workout-list">${s.items.map((item,n)=>{const ex=exerciseById(item.exerciseId);const count=a.sets.filter(x=>x.itemIndex===n).length;return `<div class="session-item ${n===a.index?'active':''}"><span class="number">${count>=item.sets?'✓':n+1}</span><button data-action="select-exercise" data-index="${n}">${ex.name}<small>${count} of ${item.sets} sets saved${a.blocked.includes(n)?', stopped':''}</small></button></div>`;}).join('')}</div><div class="timer" id="rest-card" ${!a.restUntil?'hidden':''}><div class="eyebrow" style="color:#cbd9c1">Rest and recover</div><strong id="rest-clock">${clock(rest)}</strong><p id="rest-label">${rest?'Take the rest you need.':'Rest complete. Continue when ready.'}</p><div class="button-row" style="justify-content:center"><button class="button" data-action="rest-more">Add 30 seconds</button><button class="button" data-action="rest-done">Ready to continue</button></div></div></section><p class="footer-note">Sets save as you log them. If you leave, the session can be resumed. The figure illustrates the movement and does not assess your technique.</p></aside></div>`;}
function runningWorkout(a,s){const segment=s.segments[a.runIndex];return header(s.title,`Week ${s.week} · ${s.runMinutes} minutes${s.km?` · ${s.km} km planned`:''}`,`<button class="secondary" data-action="finish-session">Finish or save partial</button>`)+`<div class="workout-layout"><section class="card"><div class="eyebrow">Your running session</div><h2>Keep a comfortable rhythm.</h2><p class="muted">${escape(s.note)}</p><div class="run-stage"><div class="eyebrow" id="run-label">${segment?escape(segment.label):'Intervals complete'}</div><div class="run-clock" id="run-clock">${clock(a.runRemaining)}</div><p class="small muted" id="run-counter">Part ${Math.min(a.runIndex+1,s.segments.length)} of ${s.segments.length}</p><div class="button-row" style="justify-content:center;margin-top:22px"><button class="primary" data-action="run-toggle" id="run-toggle" ${!segment?'disabled':''}>${a.runPlaying?'Pause timer':'Start timer'}</button><button class="secondary" data-action="run-next" ${!segment?'disabled':''}>Skip interval</button></div></div><div class="notice green">Your timer continues from elapsed time if the page is temporarily hidden. The app does not record GPS distance. Record your actual distance at the end.</div><button class="danger-button" data-action="discomfort">Stop for discomfort</button><button class="text-link" style="margin-left:15px" data-action="run-repeat">Repeat this training week</button></section><aside class="card"><h3>The session at a glance</h3><div class="run-segments">${s.segments.map((seg,n)=>`<div class="list-row"><span class="pill ${n===a.runIndex?'dark':''}">${n<a.runIndex?'✓':n+1}</span><div class="grow"><p>${seg.label}</p></div><small>${clock(seg.seconds)}</small></div>`).join('')}</div><p class="footer-note">Progress by comfort and consistency. Repeat a week if needed. Distance and pace are estimates.</p></aside></div>`;}
function updateRunning(){const {a,s}=activeData();if(!a||s?.kind!=='run'||!a.runPlaying)return;const now=Date.now();const elapsed=Math.floor((now-a.runUpdatedAt)/1000);if(elapsed<1)return;a.runUpdatedAt+=elapsed*1000;let left=elapsed;while(left>0&&a.runIndex<s.segments.length){if(left<a.runRemaining){a.runRemaining-=left;left=0;}else{left-=a.runRemaining;a.runCompleted.push(a.runIndex);a.runIndex++;a.runRemaining=s.segments[a.runIndex]?.seconds||0;}}if(a.runIndex>=s.segments.length){a.runPlaying=false;toast('Intervals complete. Review and save your session.');}persist();}
function mountPage(){if($('#hero-model')){const s=nextSession();const ex=s?.kind==='strength'?exerciseById(s.items[0]?.exerciseId):exerciseById('march');const m=mountModel($('#hero-model'),ex?.motion||'squat');m.step(.3);models.push(m);}$$('[data-preview]').forEach(c=>{const m=mountModel(c,exerciseById(c.dataset.preview).motion);m.step(.5);models.push(m);});if($('#movement-model')&&screen==='workout'){const {a,s}=activeData();models.push(mountModel($('#movement-model'),exerciseById(s.items[a.index].exerciseId).motion));}if(screen==='workout')tick=setInterval(()=>{const {a,s}=activeData();if(!a)return;if(s.kind==='run'){updateRunning();const c=$('#run-clock');if(c)c.textContent=clock(a.runRemaining);if($('#run-label'))$('#run-label').textContent=s.segments[a.runIndex]?.label||'Intervals complete';if($('#run-counter'))$('#run-counter').textContent=`Part ${Math.min(a.runIndex+1,s.segments.length)} of ${s.segments.length}`;if($('#run-toggle')){$('#run-toggle').textContent=a.runPlaying?'Pause timer':'Start timer';$('#run-toggle').disabled=a.runIndex>=s.segments.length;}}else if(a.restUntil&&$('#rest-clock')){const rest=Math.max(0,Math.ceil((a.restUntil-Date.now())/1000));$('#rest-clock').textContent=clock(rest);$('#rest-label').textContent=rest?'Take the rest you need.':'Rest complete. Continue when ready.';}},500);}
function progress(){if(!state.profile)return header('Progress you can see.','A useful record starts with your first session.')+empty('Start with a plan.','Your completed work will appear here.');const total=state.history.length,totalSets=state.history.reduce((n,h)=>n+h.sets.length,0),runKm=state.history.reduce((n,h)=>n+(h.actualKm||0),0);const start=addDays(today(),-((dayOf(today())+6)%7)-7*7);const weeks=Array.from({length:8},(_,i)=>{const date=addDays(start,i*7);return {date,count:state.history.filter(h=>h.date>=date&&h.date<addDays(date,7)).length};});const max=Math.max(4,...weeks.map(w=>w.count));const proposals=EXERCISES.filter(e=>progressionFor(e.id,state.history,state.progressionApplied).ready);return header('Your effort, made visible.','Completed work and honest feedback help you choose the next step.',`<button class="secondary" data-action="backup">Export your records</button>`)+`<div class="two-cols"><section class="card"><h3>Sessions over the last eight weeks</h3><div class="progress-chart" role="img" aria-label="Weekly recorded sessions. ${weeks.map(w=>`${dateLabel(w.date,{month:'short',day:'numeric'})}, ${w.count}`).join('. ')}">${weeks.map(w=>`<div class="bar-col"><b>${w.count}</b><div class="bar" style="height:${w.count/max*110}px"></div><span>${dateLabel(w.date,{month:'short',day:'numeric'})}</span></div>`).join('')}</div><div class="statstrip"><div class="stat"><span>Sessions</span><strong>${total}</strong></div><div class="stat"><span>Sets logged</span><strong>${totalSets}</strong></div><div class="stat"><span>Running km</span><strong>${Math.round(runKm*10)/10}</strong></div></div></section><section class="card"><div class="eyebrow">Your next step</div><h3>Progress at a pace you can recover from.</h3>${proposals.length?proposals.map(e=>`<div class="list-row"><div class="grow"><p><strong>${e.name}</strong></p><small>${progressionFor(e.id,state.history,state.progressionApplied).reason}</small></div><button class="button" data-action="progression" data-id="${e.id}">Review</button></div>`).join(''):`<p class="info-line">No increases are suggested yet. Record each prescribed set and your effort across at least two completed sessions.</p>`}<p class="small muted">Missing sets, a hard effort, or discomfort mean the movement repeats rather than automatically getting harder.</p></section></div><section class="card" style="margin-top:24px"><div class="section-head"><h2>Your training history</h2><span class="pill">${total} recorded</span></div>${[...state.history].reverse().map(historyDetail).join('')||'<p class="info-line">Your first completed or partial session will appear here.</p>'}</section>`;}
function historyDetail(h){return `<details class="history-row"><summary><span><strong>${escape(h.title)}</strong><br><small class="muted">${dateLabel(h.date)}</small></span><span>${h.sets.length} sets ${h.actualKm?` &nbsp; ${h.actualKm} km`:''}</span><span class="pill ${h.discomfort?'orange':''}">${h.status}${h.discomfort?', discomfort':''}</span></summary><div class="history-body"><p class="muted">${escape(h.note||'No extra notes.')} ${Math.round((h.durationSeconds||0)/60)} minutes recorded.</p>${h.sets.map(s=>`<div class="list-row"><div class="grow">${escape(exerciseById(s.exerciseId)?.name||s.exerciseId)}</div><span>${s.reps} ${exerciseById(s.exerciseId)?.timed?'sec':'reps'}${s.unilateral?' each side':''} ${s.kg?`at ${s.kg} kg${s.loadType==='pair'?' per hand':''}`:''}${s.band?` with ${escape(s.band)}`:''}</span></div>`).join('')}${h.kind==='run'?`<p>${h.runCompleted||0} intervals completed. ${h.actualKm?`${h.actualKm} km recorded.`:'Distance not recorded.'}</p>`:''}</div></details>`;}
function showHistoryForSession(id){const h=state.history.find(h=>h.sessionId===id);if(h)dialog(h.title,historyDetail(h).replace('<details class="history-row">','<details class="history-row" open>'));else{const s=state.sessions.find(x=>x.id===id);dialog(s?.title||'Session','<p>This session was skipped. No workout results were recorded.</p>');}}
function saveSet(form){const {a,s}=activeData();if(!a||s.kind!=='strength')return;const i=s.items[a.index],e=exerciseById(i.exerciseId);if(a.blocked.includes(a.index))return;const f=new FormData(form);a.sets.push({id:uid(),itemIndex:a.index,exerciseId:i.exerciseId,reps:Number(f.get('reps')),kg:e.load==='band'?0:Number(f.get('kg')),band:e.load==='band'?i.load.label:null,loadType:e.load||'bodyweight',unilateral:!!e.unilateral,effort:f.get('effort'),targetMax:i.max,at:new Date().toISOString(),discomfort:false});a.restUntil=Date.now()+i.rest*1000;persist();render();toast('Set saved. Take the rest you need.');}
function finishDialog(){const {a,s}=activeData();if(!a)return;if(s.kind==='run'){updateRunning();a.runPlaying=false;persist();}const complete=s.kind==='run'?a.runCompleted.length===s.segments.length&&!a.discomfort:s.items.every((i,n)=>a.sets.filter(x=>x.itemIndex===n).length>=i.sets)&&!a.discomfort;dialog(complete?'Session complete.':'Save what you did.',`<p class="muted">${complete?'Your prescribed work is recorded.':'A partial session still belongs in your history. Unfinished work is not treated as completed.'}</p><div class="review-metrics"><div><strong>${a.sets.length}</strong><span>sets logged</span></div><div><strong>${Math.round((Date.now()-a.startedAt)/60000)}</strong><span>minutes elapsed</span></div></div><form id="review-form"><label class="field">Session duration in minutes<input name="duration" type="number" min="0" max="1440" value="${Math.min(1440,Math.round((Date.now()-a.startedAt)/60000))}" required></label>${s.kind==='run'?'<label class="check"><input type="checkbox" name="runDone">I completed every planned interval, including any completed without the timer.</label>':''}<label class="field">Overall effort<select name="feeling"><option value="right">About right</option><option value="easy">Comfortable</option><option value="hard">Too hard</option></select></label>${s.kind==='run'?'<label class="field">Actual distance in km, optional<input type="number" name="actualKm" min="0" max="100" step="0.1" placeholder="Leave blank if unknown"></label>':''}<label class="check"><input type="checkbox" name="discomfort" ${a.discomfort?'checked':''}>I felt discomfort during this session.</label><label class="field">A note for next time, optional<textarea name="note" maxlength="1000" placeholder="Energy, equipment, or anything you want to remember"></textarea></label><div class="dialog-foot"><button class="secondary" type="button" data-action="close">Keep the session open</button><button class="primary" type="submit">Save ${complete?'completed':'partial'} session</button></div></form>`);}
function saveReview(form){const {a,s}=activeData();if(!a)return;const f=new FormData(form),discomfort=a.discomfort||f.has('discomfort');const complete=s.kind==='run'?(a.runCompleted.length===s.segments.length||f.has('runDone'))&&!discomfort:s.items.every((i,n)=>a.sets.filter(x=>x.itemIndex===n).length>=i.sets)&&!discomfort;const h={id:uid(),sessionId:s.id,title:s.title,date:today(),scheduledDate:s.date,kind:s.kind,status:complete?'completed':'partial',sets:structuredClone(a.sets),prescription:structuredClone(s.items),discomfort,tooHard:f.get('feeling')==='hard',feeling:f.get('feeling'),note:String(f.get('note')||''),actualKm:Number(f.get('actualKm'))||null,runCompleted:f.has('runDone')?s.segments?.length||0:a.runCompleted.length,durationSeconds:Number(f.get('duration'))*60,savedAt:new Date().toISOString()};state.history.push(h);s.status=h.status;state.active=null;persist();closeDialog();go('progress');toast('Your session is saved.');}
function moveDialog(id){const s=state.sessions.find(x=>x.id===id);if(!s||s.status!=='planned')return;dialog('Move this session',`<p class="muted">${escape(s.title)} is currently on ${dateLabel(s.date)}.</p><form id="move-form" data-id="${id}"><label class="field">New day<input type="date" name="date" min="${today()}" value="${s.date}" required></label><label class="field">Minutes available on the new day<input type="number" name="budget" min="15" max="300" value="${s.budget}" required></label><div id="move-errors" role="alert"></div><div class="dialog-foot"><button class="secondary" type="button" data-action="close">Cancel</button><button class="primary" type="submit">Move session</button></div></form>`);}
function moveSession(form){const id=form.dataset.id,s=state.sessions.find(x=>x.id===id);const f=new FormData(form),date=f.get('date'),budget=Number(f.get('budget'));const issues=scheduleConflicts(state.sessions,id,date);if(estimateSession(s)>budget*60)issues.push('This session will not fit the new time slot. Choose a longer slot or shorten the session first.');if(s.goal==='marathon'&&date>=state.profile.raceDate)issues.push('Training sessions must stay before race day.');if(issues.length){$('#move-errors').innerHTML=`<div class="error">${issues.map(x=>`<p>${escape(x)}</p>`).join('')}</div>`;return;}s.date=date;s.budget=budget;persist();closeDialog();render();toast('Session moved.');}
function swapDialog(){const {a,s}=activeData();const i=s.items[a.index];if(a.blocked.includes(a.index)){toast('This movement was stopped for discomfort. A substitute is not prescribed automatically.');return;}if(a.sets.some(x=>x.itemIndex===a.index)){toast('Keep this movement after logging sets so its record stays consistent. You can skip its remaining sets.');return;}const choices=substitutions(i,state.profile,s.location);dialog('Choose another movement',`<p class="muted">Alternatives serve the same movement role and fit your confirmed equipment. Timing is checked before applying a change.</p>${choices.map(e=>`<div class="list-row"><div class="grow"><p><strong>${e.name}</strong></p><small>${e.muscles.join(', ')}</small></div><button class="button" data-action="apply-swap" data-id="${e.id}">Choose</button></div>`).join('')||'<div class="notice">No suitable alternative is available. You can skip this movement and record a partial session.</div>'}`);}
function applySwap(id){const {a,s}=activeData();const i=s.items[a.index],e=exerciseById(id);if(!eligible(e,state.profile,s.location)||a.blocked.includes(a.index)||a.sets.some(x=>x.itemIndex===a.index))return;const replacement={...i,exerciseId:id,reps:e.timed?20:e.unilateral?6:8,min:e.timed?15:e.unilateral?5:8,max:e.timed?35:e.unilateral?10:12,load:loadFor(e,state.profile)};const copy={...s,items:s.items.map((x,n)=>n===a.index?replacement:x)};if(estimateSession(copy)>s.budget*60){toast('That variation needs more time than this session allows. Choose another or keep the current exercise.');return;}s.items[a.index]=replacement;persist();closeDialog();render();toast('Exercise changed.');}
function progressionDialog(id){const e=exerciseById(id),proposal=progressionFor(id,state.history,state.progressionApplied);if(!proposal.ready){toast(proposal.reason);return;}const planned=state.sessions.filter(s=>s.status==='planned'&&s.kind==='strength'&&s.items.some(i=>i.exerciseId===id));const next=planned[0];const item=next?.items.find(i=>i.exerciseId===id);if(!item){toast('Create a new training block to apply an adjustment to future sessions.');return;}const harder=e.harder&&exerciseById(e.harder);const canHarder=harder&&eligible(harder,state.profile,next.location);const capped=item.max>=(e.timed?60:20);dialog('Review one small change',`<p><strong>${e.name}</strong></p><p class="muted">${proposal.reason}</p><p>${canHarder?`You could try ${harder.name.toLowerCase()} in future sessions, starting at the lower end of its range.`:capped?'The repetition range is already high. Review your available resistance or discuss a suitable progression before adding more repetitions.':`You could increase the target by ${e.timed?'five seconds':'one repetition'} while keeping the same number of sets and the same resistance.`}</p><p class="small muted">Only future planned sessions change. Completed records remain as they happened. The new prescription must still fit each session.</p>`,`<button class="secondary" data-action="close">Keep it as it is</button>${!capped||canHarder?`<button class="primary" data-action="apply-progression" data-id="${id}">Apply to future sessions</button>`:''}`);}
function applyProgression(id){if(!progressionFor(id,state.history,state.progressionApplied).ready)return;const e=exerciseById(id);const updates=[];for(const s of state.sessions.filter(s=>s.status==='planned'&&s.kind==='strength')){const ix=s.items.findIndex(i=>i.exerciseId===id);if(ix<0)continue;const old=s.items[ix],harder=e.harder&&exerciseById(e.harder);let replacement;if(harder&&eligible(harder,state.profile,s.location))replacement={...old,exerciseId:harder.id,reps:harder.unilateral?5:8,min:harder.unilateral?5:8,max:harder.unilateral?10:12,load:loadFor(harder,state.profile)};else if(old.max<(e.timed?60:20))replacement={...old,reps:old.reps+(e.timed?5:1),min:old.min+(e.timed?5:1),max:old.max+(e.timed?5:1)};else continue;const copy={...s,items:s.items.map((i,n)=>n===ix?replacement:i)};if(estimateSession(copy)<=s.budget*60)updates.push([s,ix,replacement]);}if(!updates.length){toast('No future session has room for that increase. Keep the current work or allow more time.');return;}updates.forEach(([s,i,r])=>s.items[i]=r);state.progressionApplied[id]=state.history.filter(h=>h.sets.some(s=>s.exerciseId===id)).at(-1).id;persist();closeDialog();render();toast(`Updated ${updates.length} future sessions. Your previous records are unchanged.`);}
function backup(){download(JSON.stringify(state,null,2),`home-training-backup-${today()}.json`);toast('Backup downloaded. Keep it somewhere private.');}
function settingsActions(){dialog('Your data and app',`<p>Your profile, sessions and workout records are stored in this browser. They are not sent to an exercise provider. Browser data can be cleared, so export a backup regularly.</p><div class="backup-actions"><button class="primary" data-action="backup">Download backup</button><button class="secondary" data-action="import">Restore a backup</button><button class="secondary" data-action="export-calendar">Export calendar</button></div><input type="file" id="import-file" accept="application/json,.json" hidden><h3>Use it on your phone</h3><p class="small muted">Open the site in your phone browser. On iPhone, use Share then Add to Home Screen. On Android, use the browser’s Install app or Add to Home screen option. After one successful visit, the app and movement guides are available offline on browsers that support it.</p><h3>Move between devices</h3><p class="small muted">Download a backup here and restore it in the other browser. Automatic cross device syncing is not enabled.</p><details class="detail-group"><summary>Reset the app on this browser</summary><p>Download a backup first. This removes the current data from this browser. A downloaded backup can restore it.</p><button class="danger-button" data-action="reset" style="margin-top:15px">Reset local data</button></details>`);}
function about(){dialog('About Home training',`<p>A personal planner for home strength, general fitness, running and gym sessions. Exercise illustrations are original, simplified 3D diagrams. No paid exercise media is bundled.</p><p class="small muted">Training drafts and movement guides have not had an independent trainer review. They are intended for generally healthy adults, with individualisation available through the setup and workout feedback.</p><h3>Sources and further guidance</h3><ul class="small"><li><a href="https://acsm.org/resistance-training-guidelines-update-2026/" target="_blank" rel="noopener noreferrer">ACSM resistance training guidance</a></li><li><a href="https://www.cdc.gov/physical-activity-basics/guidelines/adults.html" target="_blank" rel="noopener noreferrer">CDC adult activity guidance</a></li><li><a href="https://www.nhs.uk/live-well/exercise/strength-exercises/" target="_blank" rel="noopener noreferrer">NHS strength exercises</a></li><li><a href="https://www.acefitness.org/resources/everyone/exercise-library/" target="_blank" rel="noopener noreferrer">ACE exercise library</a></li><li><a href="https://www.nhs.uk/better-health/get-active/get-running-with-couch-to-5k/" target="_blank" rel="noopener noreferrer">NHS running guidance</a></li><li><a href="https://www.bhf.org.uk/how-you-can-help/events/running-training-schedules" target="_blank" rel="noopener noreferrer">British Heart Foundation running plans</a></li></ul><p class="small muted">The running drafts are original templates. They do not reproduce or claim endorsement from these organisations. Three short workouts are a starting point and do not necessarily meet the full aerobic activity guidelines.</p><div class="button-row" style="margin-top:20px"><button class="primary" data-action="data">Data, backup and installation</button></div>`);}

document.addEventListener('submit',event=>{const form=event.target;if(!['setup-form','set-form','review-form','move-form','shorten-form'].includes(form.id))return;event.preventDefault();if(!form.reportValidity())return;if(form.id==='setup-form')previewPlan();if(form.id==='set-form')saveSet(form);if(form.id==='review-form')saveReview(form);if(form.id==='move-form')moveSession(form);if(form.id==='shorten-form'){const id=form.dataset.id,source=state.sessions.find(s=>s.id===id),result=shortenSession(source,Number(new FormData(form).get('budget')),state.active?.sessionId===id?state.active.sets:[]);if(result.error){$('#shorten-error').innerHTML=`<div class="error">${escape(result.error)}</div>`;return;}Object.assign(source,result.session);persist();closeDialog();render();toast('A shorter session is ready. Recorded sets stay unchanged.');}});
document.addEventListener('change',async event=>{const t=event.target;if(t.closest('#setup-form')){captureSetup();if(t.name==='goal')$('#running-setup').hidden=!['running','marathon'].includes(setupDraft.goal);}
 if(t.id==='pattern-filter'){libraryPattern=t.value;render();}if(t.id==='availability-filter'){libraryAvailability=t.value;render();}if(t.id==='model-speed')(modalModel||models.at(-1))?.setSpeed(t.value);if(t.id==='import-file'&&t.files[0]){const file=t.files[0];if(file.size>5*1024*1024){toast('Choose a backup smaller than 5 MB.');return;}try{const incoming=JSON.parse(await file.text());if(!validState(incoming))throw Error('invalid');dialog('Restore this backup?',`<p>This replaces the records currently in this browser with ${incoming.history.length} recorded sessions and ${incoming.sessions.length} scheduled sessions.</p><p class="small muted">Download your current backup before replacing it if you want to keep both.</p>`,`<button class="secondary" data-action="backup">Back up current data</button><button class="primary" id="restore-confirm">Restore backup</button>`);$('#restore-confirm').onclick=()=>{state=incoming;state.progressionApplied??={};setupDraft=state.profile?structuredClone(state.profile):defaultProfile();persist();try{localStorage.removeItem(DRAFT);}catch{}closeDialog();go('home');toast('Backup restored.');};}catch{toast('That file is not a valid Home training backup. Your current records were not changed.');}}});
document.addEventListener('input',event=>{if(event.target.id==='exercise-search'){libraryQuery=event.target.value;const position=event.target.selectionStart;render();const input=$('#exercise-search');input.focus();if(position!==null)input.setSelectionRange(position,position);}if(event.target.id==='model-step'){(modalModel||models.at(-1))?.step(event.target.value);const button=(event.target.closest('dialog')||$('#main')).querySelector('[data-model="play"]');if(button)button.textContent='Play';}});
document.addEventListener('click',event=>{const nav=event.target.closest('[data-nav]');if(nav){go(nav.dataset.nav);return;}const model=event.target.closest('[data-model]');if(model){const control=modalModel||models.at(-1);if(model.dataset.model==='play'){control?.play();model.textContent=model.textContent==='Pause'?'Play':'Pause';}else control?.[model.dataset.model]?.();return;}const b=event.target.closest('[data-action]');if(!b)return;const id=b.dataset.id,action=b.dataset.action;
 if(action==='close')closeDialog();if(action==='setup')go('settings');if(action==='schedule')go('schedule');if(action==='about')about();if(action==='data')settingsActions();if(action==='backup')backup();if(action==='import')$('#import-file')?.click();if(action==='resume')go('workout');if(action==='open-session')startSession(id);if(action==='exercise-guide')exerciseGuide(id);if(action==='accept-plan'&&pendingPlan){state.profile=structuredClone(setupDraft);state.sessions=state.sessions.filter(s=>s.status!=='planned').concat(pendingPlan.sessions);state.planSummary=pendingPlan.summary;state.planWarnings=pendingPlan.warnings;pendingPlan=null;persist();try{localStorage.removeItem(DRAFT);}catch{}closeDialog();go('home');toast('Your programme is ready.');}
 if(action==='prev-week'){weekOffset--;render();}if(action==='next-week'){weekOffset++;render();}if(action==='this-week'){weekOffset=0;render();}if(action==='export-calendar'){if(!state.profile||!state.sessions.some(s=>s.status==='planned')){toast('Create a programme before exporting a calendar.');return;}download(calendarICS(state.sessions,state.profile),'home-training-calendar.ics','text/calendar');toast('Calendar downloaded. Import it into your calendar app.');}
 if(action==='move-session')moveDialog(id);if(action==='skip-session'){const s=state.sessions.find(x=>x.id===id);dialog('Skip this session?',`<p>${escape(s.title)} will stay in the schedule as skipped. No completed work will be added to your history.</p>`,`<button class="secondary" data-action="close">Keep session</button><button class="primary" id="confirm-skip">Skip session</button>`);$('#confirm-skip').onclick=()=>{s.status='skipped';persist();closeDialog();render();toast('Session skipped. The next workout keeps its original workload.');};}
 if(action==='finish-session')finishDialog();if(action==='select-exercise'){state.active.index=Number(b.dataset.index);persist();render();}if(action==='next-exercise'){const {a,s}=activeData();if(a.index<s.items.length-1){a.index++;persist();render();}else finishDialog();}if(action==='rest-more'){state.active.restUntil=Math.max(state.active.restUntil||0,Date.now())+30000;persist();render();}if(action==='rest-done'){state.active.restUntil=null;persist();render();}if(action==='swap-exercise')swapDialog();if(action==='apply-swap')applySwap(id);
 if(action==='discomfort'){const {a,s}=activeData();a.discomfort=true;if(s.kind==='strength'){if(!a.blocked.includes(a.index))a.blocked.push(a.index);a.sets.filter(x=>x.itemIndex===a.index).forEach(x=>x.discomfort=true);}else a.runPlaying=false;persist();render();toast('Stop this movement. Progression is paused. Seek appropriate advice for pain or other concerning symptoms.');}if(action==='run-toggle'){const {a}=activeData();updateRunning();a.runPlaying=!a.runPlaying;a.runUpdatedAt=Date.now();persist();render();}if(action==='run-next'){const {a,s}=activeData();a.runIndex++;a.runRemaining=s.segments[a.runIndex]?.seconds||0;a.runUpdatedAt=Date.now();if(a.runIndex>=s.segments.length)a.runPlaying=false;persist();render();}
 if(action==='run-repeat'){const {s}=activeData();dialog('Repeat this training week?',`<p>A repeat gives you more time at this workload. The following running weeks move seven days later. Completed records stay unchanged.</p>`,`<button class="secondary" data-action="close">Cancel</button><button class="primary" id="confirm-repeat">Repeat week</button>`);$('#confirm-repeat').onclick=()=>{const result=repeatRunningWeek(state.sessions,s,state.profile.raceDate);if(result.error){toast(result.error);return;}state.sessions=result.sessions;persist();closeDialog();toast('A repeat week was added. Review the updated schedule.');};}
 if(action==='shorten'){const session=state.sessions.find(s=>s.id===id);dialog('Make this session shorter',`<p>Reduce sets while keeping the movements, recorded work and suitable rest. The full time estimate is checked again.</p><form id="shorten-form" data-id="${id}"><label class="field">Available minutes<input name="budget" type="number" min="15" max="${session.budget}" value="${Math.max(15,session.budget-5)}" required></label><div id="shorten-error" role="alert"></div><div class="dialog-foot"><button class="secondary" type="button" data-action="close">Cancel</button><button class="primary" type="submit">Use shorter session</button></div></form>`);}

 if(action==='progression')progressionDialog(id);if(action==='apply-progression')applyProgression(id);if(action==='reset'){dialog('Reset this browser?',`<p>This removes your profile, schedule and workout records from this browser. A downloaded backup can restore them.</p>`,`<button class="secondary" data-action="backup">Download backup first</button><button class="danger-button" id="confirm-reset">Reset this browser</button>`);$('#confirm-reset').onclick=()=>{state=blank();setupDraft=defaultProfile();persist();try{localStorage.removeItem(DRAFT);}catch{}closeDialog();go('home');};}
});
document.addEventListener('visibilitychange',()=>{if(!document.hidden){updateRunning();if(screen==='workout'&&state.active)render();}});
// Keep data controls available next to the setup form without collecting extra information.
const observer=new MutationObserver(()=>{if(screen==='settings'&&!$('#data-controls')){const main=$('#main');if(main){const div=document.createElement('div');div.id='data-controls';div.className='button-row';div.innerHTML='<button class="secondary" data-action="data">Data, backup and installation</button><button class="quiet-button" data-action="about">About the training guidance</button>';main.append(div);}}});observer.observe($('#app'),{childList:true,subtree:true});
if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
if(!state.profile)screen='settings';render();
